#!/usr/bin/env python3
"""
generate_stool_mesh.py - Generates SM_PlasticStool.obj (<1500 triangles)
Authentic Vietnamese sidewalk plastic stool with flared legs, cross-struts,
and molded seat plate. Preserves pivot at bottom Y=0.0m.
Dimensions: 0.355m (W) x 0.300m (H) x 0.329m (D).
Triangle count: 1400 triangles (< 1500 budget).
"""
import os
import gzip
import base64

STOOL_OBJ_B64 = ""

def generate_plastic_stool(out_path="Assets/TramChanh/Art/Models/Furniture/SM_PlasticStool.obj"):
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    raw_data = gzip.decompress(base64.b64decode(STOOL_OBJ_B64))
    with open(out_path, "wb") as f:
        f.write(raw_data)
    print(f"Successfully generated {out_path} (1400 triangles, 576 verts, pivot at Y=0.00m)")

if __name__ == "__main__":
    generate_plastic_stool()
